begin;
select plan(26);
-- Metadata fixtures here exercise SQL/RLS; the browser gate uploads actual raster bytes.
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select public.approve_calendar('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1);
select set_config('test.copy_job',public.enqueue_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',1)::text,true);
select set_config('test.lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000101')),true);
select throws_ok($$select public.finish_copy_job(current_setting('test.copy_job')::uuid,null,'{}')$$,'PT409','Lease unavailable','null lease cannot bypass lock');
select lives_ok($$select public.finish_copy_job(current_setting('test.copy_job')::uuid,current_setting('test.lease')::uuid,'{"brandRevision":1,"synthetic":true,"subject":"Field notes","subjects":["Field notes","A considered layer","Explore the details"],"preheader":"Original fixture","body":"A fictional overshirt to explore at your own pace.","cta":"Explore","url":"https://cedar-lane.example/products/overshirt"}')$$,'leased copy job persists a new version');
select is((select copy_revision from public.campaigns where id='00000000-0000-4000-8000-000000000601'),2,'copy revision incremented');
select throws_ok($$select public.finish_copy_job(current_setting('test.copy_job')::uuid,current_setting('test.lease')::uuid,'{}')$$,'PT409','Lease unavailable','replay cannot create a second content revision');
select lives_ok($$select public.approve_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2)$$,'owner approves current copy');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.approve_copy('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',2)$$,'42501','Access denied','operator cannot creatively approve copy');
select set_config('test.assignment',public.assign_campaign('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601','00000000-0000-4000-8000-000000000201',2)::text,true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select is((select count(*)::integer from public.campaigns),0,'assigned designer still cannot enumerate tenant campaigns');
select is((select count(*)::integer from public.designer_assignments),1,'designer sees assignment only');
select lives_ok($$select public.assignment_brief(current_setting('test.assignment')::uuid)$$,'designer reads approved scoped pack');
select throws_ok($$select public.assignment_brief('00000000-0000-4000-8000-000000000999')$$,'42501','Assignment unavailable','unrelated assignment denied');
reset role;
insert into storage.objects(bucket_id,name) values('designer-submissions','00000000-0000-4000-8000-000000000101/'||current_setting('test.assignment')||'/fixture-one.png'),('designer-submissions','00000000-0000-4000-8000-000000000101/'||current_setting('test.assignment')||'/fixture-two.png');
select public.record_design_upload(current_setting('test.assignment')::uuid,'00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000101/'||current_setting('test.assignment')||'/fixture-one.png',repeat('a',64),'image/png',100);
select public.record_design_upload(current_setting('test.assignment')::uuid,'00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000101/'||current_setting('test.assignment')||'/fixture-two.png',repeat('b',64),'image/png',100);
set local role authenticated;
select set_config('test.first_submission',public.submit_design(current_setting('test.assignment')::uuid,3,'00000000-0000-4000-8000-000000000101/'||current_setting('test.assignment')||'/fixture-one.png','Original synthetic design')::text,true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.review_design('00000000-0000-4000-8000-000000000101',current_setting('test.first_submission')::uuid,4,'revision','hero','Increase the hero breathing room.')$$,'owner requests section-specific revision');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select set_config('test.final_submission',public.submit_design(current_setting('test.assignment')::uuid,4,'00000000-0000-4000-8000-000000000101/'||current_setting('test.assignment')||'/fixture-two.png','Revised original synthetic design')::text,true);
select is((select count(*)::integer from public.designer_submissions),2,'resubmission preserves history');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.review_design('00000000-0000-4000-8000-000000000101',current_setting('test.final_submission')::uuid,5,'approved','whole','Approved')$$,'42501','Access denied','operator cannot approve final design');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.review_design('00000000-0000-4000-8000-000000000101',current_setting('test.first_submission')::uuid,4,'approved','whole','Approved')$$,'PT409','Stale design version','old submission approval rejected');
select lives_ok($$select public.review_design('00000000-0000-4000-8000-000000000101',current_setting('test.final_submission')::uuid,5,'approved','whole','Owner approved')$$,'owner approves exact final version');
select throws_ok($$select public.create_delivery_package('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',7,'{}')$$,'23514','Footer, HTTPS links and sender required','missing footer blocks package');
select set_config('test.package',public.create_delivery_package('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',7,'{"senderName":"Synthetic Cedar","senderEmail":"studio@cedar-lane.example","address":"42 Fictional Lane, Demo Town","unsubscribeUrl":"https://cedar-lane.example/unsubscribe","privacyUrl":"https://cedar-lane.example/privacy","html":"<script>caller injection must be ignored</script>"}')::text,true);
select ok((select snapshot->>'html' not like '%<script>%' from public.delivery_packages where id=current_setting('test.package')::uuid),'caller HTML never replaces approved content');
select set_config('test.schedule_job',public.enqueue_delivery('00000000-0000-4000-8000-000000000101',current_setting('test.package')::uuid,8)::text,true);
select set_config('test.schedule_lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000101')),true);
select public.fixture_delivery_command(current_setting('test.schedule_job')::uuid,current_setting('test.schedule_lease')::uuid,'reconcile');
select lives_ok($$select public.fixture_delivery_command(current_setting('test.schedule_job')::uuid,current_setting('test.schedule_lease')::uuid,'prepare')$$,'provider preparation persisted');
select lives_ok($$select public.fixture_delivery_command(current_setting('test.schedule_job')::uuid,current_setting('test.schedule_lease')::uuid,'schedule')$$,'provider confirms schedule separately');
select lives_ok($$select public.finish_delivery_job(current_setting('test.schedule_job')::uuid,current_setting('test.schedule_lease')::uuid)$$,'confirmed provider state completes durable intent');
select is((select count(*)::integer from public.fixture_deliveries),1,'exactly one remote fixture record');
select is(public.enqueue_delivery('00000000-0000-4000-8000-000000000101',current_setting('test.package')::uuid,8)::text,current_setting('test.schedule_job'),'replayed scheduling intent returns original job');
select set_config('test.cancel_job',public.enqueue_cancel('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000601',8)::text,true);
select set_config('test.cancel_lease',(select lease_token::text from public.claim_job('00000000-0000-4000-8000-000000000101')),true);
select public.fixture_delivery_command(current_setting('test.cancel_job')::uuid,current_setting('test.cancel_lease')::uuid,'reconcile');
select public.fixture_delivery_command(current_setting('test.cancel_job')::uuid,current_setting('test.cancel_lease')::uuid,'cancel');
select public.finish_delivery_job(current_setting('test.cancel_job')::uuid,current_setting('test.cancel_lease')::uuid);
select is((select delivery_state from public.campaigns where id='00000000-0000-4000-8000-000000000601'),'cancelled','cancellation only follows confirmed provider result');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select is((select count(*)::integer from public.delivery_packages),0,'other tenant cannot read package');
select is((select count(*)::integer from public.designer_submissions),0,'other tenant cannot read design artifacts');
select is((select count(*)::integer from public.notifications),0,'notifications remain recipient and tenant scoped');
select * from finish();
rollback;
